'use strict';
let currentQuote='';function calculateQuote(){try{let q=planQuote(document.querySelector('#plan').value,document.querySelector('#cycle').value,document.querySelector('#code').value),yen=n=>'¥'+n.toLocaleString('ja-JP');currentQuote=`PATCHFLOW 導入見積もり（検討用・契約ではありません）\n${PatchflowPlans[q.plan].name} / ${q.cycle==='annual'?'年払い':'月払い'}\n通常 ${yen(q.base)} / 割引 ${yen(q.discount)}\n初回 ${yen(q.total)} / 次回 ${yen(q.renewal)}\nコード ${q.code||'なし'}\n課金・利用権の発行は未開始。税の扱いは正式提供時に確定。`;document.querySelector('#quote').textContent=currentQuote;document.querySelector('#savequote').disabled=false}catch(e){currentQuote='';document.querySelector('#quote').textContent=e.message;document.querySelector('#savequote').disabled=true}}
document.querySelector('#apply').onclick=calculateQuote;for(let id of ['plan','cycle'])document.querySelector('#'+id).onchange=calculateQuote;document.querySelector('#code').oninput=()=>{currentQuote='';document.querySelector('#savequote').disabled=true;document.querySelector('#quote').textContent='コードを適用するには計算してください'};document.querySelector('#savequote').onclick=()=>{if(!currentQuote)return;let url=URL.createObjectURL(new Blob([currentQuote],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='patchflow-plan-quote.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};calculateQuote();
